use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf},collections::{BTreeMap,BTreeSet}};
const R:&str="/home/ubuntu/src/zopro-perf-work/coarse-proof-phase-entry176";
fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn receipt(p:&Path)->Value{let e=read(p.join("exit.json"));for k in["stdout","stderr"]{assert_eq!(hash(p.join(format!("{k}.log"))),e[format!("{k}_sha256")].as_str().unwrap());}e}
fn main(){assert!(!r("failure-review.json").exists());let mut ledger:BTreeSet<String>=serde_json::from_value(read(r("prior-proof-sha256.json"))).unwrap();assert_eq!(ledger.len(),30710);let mut pins=0;for n in["build-pins.json","link-pins.json","pins.json"]{for(p,h)in read(r(n)).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pins+=1;}}
 let plan=read(r("plan.json"));let(mut ok,mut failed)=(0,0);for step in plan["steps"].as_array().unwrap(){let name=step["name"].as_str().unwrap();let p=r("runs").join(name);if !p.exists(){continue;}let e=receipt(&p);if e["success"]==true{assert_eq!(e["returncode"],0);ok+=1;}else{failed+=1;assert_eq!(name,"preflight-4x2-w32-ON");assert_eq!(e["returncode"],101);let s=fs::read_to_string(p.join("stderr.log")).unwrap();assert!(s.contains("required phase canonical")&&s.contains("left: 0")&&s.contains("right: 2"));}}assert_eq!(ok,14);assert_eq!(failed,1);assert!(!r("runs/result.json").exists());for d in["stat","perf"]{assert_eq!(fs::read_dir(r(d)).unwrap().count(),0);}
 let mut inventory=vec![];let mut vk=BTreeMap::new();let(mut new,mut reused,mut graphs)=(0,0,0);for j in read(r("jobs.json")).as_array().unwrap(){let name=j["name"].as_str().unwrap();let reuse=j["reused_from"].is_string();let vp=j["reused_verify_from"].as_str().map(PathBuf::from).unwrap_or_else(||r(format!("runs/verify-{name}")));if !vp.join("exit.json").exists(){continue;}assert_eq!(receipt(&vp)["success"],true);let rp=j["reused_from"].as_str().map(PathBuf::from).unwrap_or_else(||r("runs").join(name));assert_eq!(receipt(&rp)["success"],true);let dir=Path::new(j["directory"].as_str().unwrap());let proof=dir.join("0.proof");assert_eq!(fs::metadata(&proof).unwrap().len(),164);assert_eq!(hash(dir.join("0.public")),j["case"]["public_sha256"]);let text=fs::read_to_string(vp.join("stdout.log")).unwrap();let rows=text.lines().filter_map(|l|l.strip_prefix("VERIFIED ")).collect::<Vec<_>>();assert_eq!(rows.len(),1);let f=rows[0].split_whitespace().map(|l|l.split_once('=').unwrap()).collect::<BTreeMap<_,_>>();let h=hash(&proof);assert_eq!(f["proof_sha256"],h);assert_eq!(f["image_sha256"],j["case"]["image_sha256"]);assert_eq!(f["public_sha256"],j["case"]["public_sha256"]);if let Some(old)=vk.insert(j["case"]["shape"].as_str().unwrap().to_string(),f["vk_sha256"].to_string()){assert_eq!(old,f["vk_sha256"]);}if reuse{assert!(ledger.contains(&h));reused+=1;}else{assert!(ledger.insert(h.clone()));new+=1;}
  let stdout=fs::read_to_string(rp.join("stdout.log")).unwrap();for g in stdout.lines().filter_map(|l|l.strip_prefix("GRAPH ")){let g:Value=serde_json::from_str(g).unwrap();assert_eq!(g["faults"],0);if j["case"]["shape"]=="1x2"{assert_eq!(g["entry_hops"],1);}assert!(g["entries"].as_array().unwrap().iter().any(|e|e["phase"]=="canonical"&&e["state"]==2));graphs+=1;}
  inventory.push(json!({"name":name,"proof_sha256":h,"public_sha256":f["public_sha256"],"image_sha256":f["image_sha256"],"vk_sha256":f["vk_sha256"],"reused":reuse,"verified":true}));
 }
 assert_eq!(new,7);assert_eq!(reused,1);assert_eq!(graphs,2);assert_eq!(ledger.len(),30717);for d in["native","cubic","links"]{assert_eq!(read(r(format!("{d}/result.json")))["status"],"complete");}
 fs::write(r("proof-sha256-after-failure.json"),serde_json::to_vec_pretty(&ledger).unwrap()).unwrap();fs::write(r("proof-inventory-after-failure.json"),serde_json::to_vec_pretty(&inventory).unwrap()).unwrap();let out=json!({"passed":true,"pin_occurrences":pins,"native_core_tests":130,"prover_raw_tests":2,"cubic_tests":6,"distinct_new_recorder_cases":5,"successful_qualification_and_link_commands":6,"successful_capture_commands":14,"failed_capture_commands":1,"failure":"4x2 uses original noncanonical CPU path, outside this recorder's canonical hooks","primary_entry_transport_graph_complete":true,"saved_complete_graphs":2,"native_entry_hop_verified_in_primary_graph":true,"new_independent_exports":7,"reused_exports":1,"prior_proof_count":30710,"independent_proof_count":30717,"new_internally_verified_SDK_requests_before_abort":29,"qualified_or_completed_requests_including_reused":33,"latency_callers_started":0,"PMU_or_cycles_recordings_started":0,"production_changed":false,"adopted":false,"goal_achieved":false});fs::write(r("failure-review.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("{out}");}
